(()=>{'use strict';const bars=[...document.querySelectorAll('[data-tools-filter-bar]')];if(!bars.length)return;bars.forEach(bar=>{const buttons=[...bar.querySelectorAll('[data-category-filter]')],sections=[...document.querySelectorAll('.tool-category-section[data-category]')];const apply=key=>{buttons.forEach(btn=>{const on=btn.dataset.categoryFilter===key;btn.classList.toggle('is-active',on);btn.setAttribute('aria-pressed',String(on));});sections.forEach(sec=>{const show=key==='all'||sec.dataset.category===key;sec.hidden=!show;if(show){sec.classList.remove('is-filter-reveal');requestAnimationFrame(()=>sec.classList.add('is-filter-reveal'));}});bar.dataset.activeFilter=key;};buttons.forEach(btn=>btn.addEventListener('click',()=>apply(btn.dataset.categoryFilter)));});})();